import { supabase } from '@/integrations/supabase/client';
import { Patient } from '@/types';
import { isNetworkError } from '@/lib/offlineSync';
import { queueOfflinePatientRegistration } from '@/lib/offlinePatientRegistration';
import { searchPatientDirectory } from '@/lib/patientDirectory';

/* ============================================================
   Real Supabase-backed helpers (replaces previous mocks)
   ============================================================ */

/** Insert a patient. patient_code is auto-generated by a DB trigger if not provided. */
export async function registerPatient(payload: any) {
  // getSession() reads the persisted Supabase session and therefore remains
  // usable while the device is offline. Server authorization still occurs
  // when the queued command is replayed.
  const { data: sessionData, error: authError } = await supabase.auth.getSession();
  if (authError) throw authError;
  const user = sessionData.session?.user;
  if (!user) throw new Error('You must be signed in to register a patient.');

  const membershipType = payload.membershipType === 'temporary' ? 'temporary' : 'permanent';
  const insertRow = {
    patient_code: payload.patientId || null,
    membership_type: membershipType,
    membership_expires_at: payload.membershipExpiresAt || null,
    registration_reason: payload.registrationReason || null,
    first_name: payload.firstName,
    last_name: payload.lastName,
    date_of_birth: payload.dateOfBirth || null,
    gender: payload.gender || null,
    email: payload.email || null,
    phone: payload.phone || null,
    address: payload.address || null,
    city: payload.city || null,
    ghana_card_number: payload.ghanaCardNumber || null,
    blood_group: payload.bloodType || null,
    genotype: payload.genotype || null,
    allergies: payload.allergies || null,
    chronic_conditions: payload.chronicConditions || null,
    insurance_provider: payload.insuranceProvider || null,
    insurance_number: payload.policyNumber || null,
    insurance_group_number: payload.groupNumber || null,
    insurance_expiry: payload.insuranceExpiry || null,
    emergency_contact_name: payload.emergencyName || null,
    emergency_contact_phone: payload.emergencyPhone || null,
    emergency_contact_relation: payload.emergencyRelation || null,
    created_by: user.id,
  };

  // Registration is an explicit offline workflow. It deliberately does not
  // queue document uploads: files require Storage-specific offline handling.
  if (typeof navigator !== 'undefined' && !navigator.onLine) {
    const queued = await queueOfflinePatientRegistration(insertRow);
    return {
      success: true,
      offlineQueued: true,
      patientId: queued.patientCode,
      patient: queued.row,
    };
  }

  try {
    const { data, error } = await supabase.rpc('register_patient_workflow', { _patient: insertRow });
    if (error) throw error;
    return { success: true, offlineQueued: false, patientId: data.patient_code, patient: data };
  } catch (error) {
    if (!isNetworkError(error)) throw error;

    const queued = await queueOfflinePatientRegistration(insertRow);
    return {
      success: true,
      offlineQueued: true,
      patientId: queued.patientCode,
      patient: queued.row,
    };
  }
}

export async function searchPatients(query: string) {
  const { data, error } = await searchPatientDirectory(query, 50);
  if (error) { console.error('[searchPatients]', error); return []; }
  const q = query.trim().toLocaleLowerCase();
  const ranked = (data ?? []).map((p) => {
    const fields = [p.patient_code, p.first_name, p.last_name, p.phone, p.ghana_card_number, p.insurance_number].filter(Boolean).map((value) => String(value).toLocaleLowerCase());
    const score = fields.reduce((best, field) => {
      if (!q) return Math.max(best, 1);
      if (field === q) return Math.max(best, 100);
      if (field.startsWith(q)) return Math.max(best, 75);
      if (field.includes(q)) return Math.max(best, 50);
      return best;
    }, 0);
    return {
      score,
      patient: {
        id: p.id,
        patientId: p.patient_code,
        firstName: p.first_name,
        lastName: p.last_name,
        fullName: `${p.first_name} ${p.last_name}`,
        phone: p.phone,
        ghanaCardNumber: p.ghana_card_number,
        status: p.status,
        insuranceProvider: p.insurance_provider,
        membershipType: undefined,
        membershipExpiresAt: undefined,
      },
    };
  });
  return ranked.sort((a, b) => b.score - a.score).map(({ patient }) => patient);
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

async function fetchPatientProfile(patientId: string) {
  const { data, error } = await supabase.rpc('get_patient_profile_for_user' as never, { _patient_id: patientId } as never);
  if (error) throw error;
  const rows = Array.isArray(data) ? data : data ? [data] : [];
  return rows[0] ?? null;
}

/**
 * Resolve Patient Hub links by the canonical patient UUID first. Some legacy
 * links contain the hospital patient code instead; only fall back to an exact
 * code match through the facility-scoped directory, then fetch the profile
 * through the same authorized RPC. This does not bypass facility authorization.
 */
export async function getPatientById(id: string) {
  const requestedId = id.trim();
  if (!requestedId) return null;

  if (UUID_PATTERN.test(requestedId)) {
    const profile = await fetchPatientProfile(requestedId);
    if (profile) return profile;
  }

  const { data: matches, error } = await searchPatientDirectory(requestedId, 10);
  if (error) throw error;
  const exactMatch = (matches ?? []).find(
    (candidate) => String(candidate.patient_code ?? '').trim().toLocaleLowerCase() === requestedId.toLocaleLowerCase(),
  );
  if (!exactMatch) return null;

  return fetchPatientProfile(exactMatch.id);
}
export async function updatePatient(id: string, data: Partial<Patient>) {
  const updateRow = {
    patient_code: data.patientId,
    first_name: data.firstName,
    last_name: data.lastName,
    date_of_birth: data.dateOfBirth,
    gender: data.gender,
    email: data.email,
    phone: data.phone,
    address: data.address,
    ghana_card_number: data.ghanaCardNumber,
    city: data.city,
    insurance_provider: data.insuranceProvider,
    insurance_number: data.insuranceNumber ?? data.insurance?.policyNumber,
    insurance_group_number: data.insuranceGroupNumber ?? data.insurance?.groupNumber,
    insurance_expiry: data.insuranceExpiry ?? data.insurance?.expiryDate,
    emergency_contact_name: data.emergencyContact?.name,
    emergency_contact_phone: data.emergencyContact?.phone,
    emergency_contact_relation: data.emergencyContact?.relationship,
    blood_group: data.bloodType,
    genotype: data.genotype,
    allergies: Array.isArray(data.allergies) ? data.allergies.join(', ') : data.allergies,
    chronic_conditions: Array.isArray(data.chronicConditions) ? data.chronicConditions.join(', ') : data.chronicConditions,
    status: data.status,
  };
  const cleanRow = Object.fromEntries(Object.entries(updateRow).filter(([, value]) => value !== undefined));
  const { data: updated, error } = await supabase.rpc('update_patient_workflow', { _patient_id: id, _changes: cleanRow });
  if (error) throw error;
  return { success: true, patient: updated };
}

/* ============================================================
   Document safety / analysis helpers
   ============================================================ */
const MAX_DOCUMENT_SIZE_BYTES = 10 * 1024 * 1024;
const SUPPORTED_DOCUMENT_TYPES = new Set(['application/pdf','image/jpeg','image/png','image/webp','image/tiff','text/plain']);
async function sha256File(file: File): Promise<string> { const buffer=await file.arrayBuffer(); const digest=await crypto.subtle.digest('SHA-256',buffer); return Array.from(new Uint8Array(digest)).map((byte)=>byte.toString(16).padStart(2,'0')).join(''); }
export async function analyzeDocument(document: File) {
  if (!document || document.size === 0) return { success:false, findings:['The selected document is empty and cannot be processed.'] };
  if (document.size > MAX_DOCUMENT_SIZE_BYTES) return { success:false, findings:['The selected document exceeds the 10 MB upload limit.'] };
  const type=document.type||'application/octet-stream';const fingerprint=await sha256File(document);const findings=[`Document accepted: ${document.name}`,`MIME type: ${type}`,`Size: ${(document.size/1024).toFixed(1)} KB`,`SHA-256 fingerprint: ${fingerprint}`];
  findings.push(SUPPORTED_DOCUMENT_TYPES.has(type)?'File integrity metadata generated successfully.':'The file type is not in the supported clinical-document set. Review before attaching it to the patient record.');
  findings.push('No diagnosis, medication-interaction assessment, or treatment recommendation was generated from this upload. Clinical OCR/AI extraction must be explicitly configured and reviewed by an authorized clinician.');
  return { success:true, findings, fingerprint };
}
export function registerPatientFromDocument(_document: File) { return Promise.resolve({ success:false, extracted:{}, message:'Clinical document extraction requires a configured, access-controlled OCR service.' }); }
export function verifyGhanaCard(cardNumber: string) { return Promise.resolve({ success:cardNumber.startsWith('GHA'), verified:false, authority:'National Identification Authority Ghana', message:'Format validation only. This does not verify the identity or authenticity of a Ghana Card.' }); }
